# 江阴智慧物业 C端 H5 (D:\repository\江阴H5) 本地 nginx 部署 —— root 指向本项目 dist
# 代理对齐 env/.env 的 VITE_APP_PROXY_PREFIX=/api 与 VITE_SERVER_BASEURL
#   H5 请求形如 /api/v2.0/xxx -> 去掉 /api 前缀转发到网关 host（与 vite dev proxy rewrite 一致）
server {
    listen 8102;
    server_name localhost;
    root D:/repository/江阴H5/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host unlimited.g.h5.admin.web.v2.wuguan.all.huaian.dev.zhi.com;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }

    # 业务 API：/api/ 去前缀转发网关（rewrite 去掉 /api）
    location /api/ {
        rewrite ^/api/(.*)$ /$1 break;
        proxy_pass http://unlimited.g.h5.admin.web.v2.wuguan.all.huaian.dev.zhi.com;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}
